fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since a and b have the same length as per problem statement,
    // zip safely iterates through both together,
    // then compare each pair after upcasting to i32.
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| (x as i32) > (y as i32))
     .collect()
}